/// Editorial English adaptations of the existing reflections, not verbatim quotations.
/// This presentation projection never updates persisted records or selection IDs.
public extension DailyReflection {
  var englishPresentation: DailyReflection {
    guard let entry = EnglishReflectionAdaptations.entries[id] else { return self }
    return DailyReflection(id: id, text: entry.0, attribution: "Inspired by " + entry.1,
      work: entry.2, source: .ideaAdaptation, provenance: provenance)
  }
}
